const grid = document.querySelector('#product-grid');
const result = document.querySelector('#result');
const brandFilter = document.querySelector('#brand-filter');
const modelFilter = document.querySelector('#model-filter');
const vehicleResults = document.querySelector('#vehicle-results');
const sideFilter = document.querySelector('#side-filter');
const search = document.querySelector('#search');
const typeButtons = document.querySelectorAll('[data-type]');
const detail = document.querySelector('#detail');
const more = document.querySelector('#more');
const pageSize = 16;
let selectedType = 'all';
let limit = pageSize;

const brands = [...new Set(products.flatMap(product => product.fit.map(([brand]) => brand)))];
brands.sort((first, second) => first.localeCompare(second, 'tr'));
for (const brand of brands) brandFilter.add(new Option(brand, brand));

function normalize(value) {
  return value.toLocaleLowerCase('tr').normalize('NFD').replace(/\p{Diacritic}/gu, '').replaceAll('ı', 'i').trim();
}

function productLabel(product) {
  return product.type === 'cover' ? 'Ayna kapağı' : 'Komple yan ayna';
}

function imagePath(product) {
  return `assets/products/${product.code}.png`;
}

const featureImages = {"complete": "data:image/png;base64,", "primer": "data:image/png;base64,", "electric": "data:image/png;base64,", "fold": "data:image/png;base64,", "puddle": "data:image/png;base64,", "heat": "data:image/png;base64,", "manual": "data:image/png;base64,", "turn": "data:image/png;base64,", "temp": "data:image/png;base64,", "memory": "data:image/png;base64,"};

const featureIcons = {
  'Komple ayna': 'complete', 'Elektrikli ayar': 'electric',
  'Mekanik ayar': 'manual', 'Isıtmalı': 'heat', 'Astar kaplı': 'primer',
  'Katlanır': 'fold', 'Sinyalli': 'turn', 'Hafızalı': 'memory',
  'Zemin aydınlatması': 'puddle', 'Sıcaklık sensörü': 'temp',
};

function featureBadges(specs) {
  return specs.map(spec => {
    const item = document.createElement('li');
    if (featureIcons[spec]) {
      const icon = document.createElement('img');
      icon.alt = '';
      icon.src = featureImages[featureIcons[spec]];
      item.append(icon);
    } else {
      const symbol = document.createElement('span');
      symbol.className = spec === 'Siyah' ? 'color-swatch' : 'cover-symbol';
      symbol.setAttribute('aria-hidden', 'true');
      item.append(symbol);
    }
    item.append(spec);
    return item;
  });
}

function vehicleCard([brand, model, years, photo], tag = 'li') {
  const card = document.createElement(tag);
  const image = document.createElement('img');
  image.src = `assets/vehicles/${photo}.png`;
  image.alt = `${brand} ${model}`;
  image.loading = 'lazy';
  const label = document.createElement('span');
  label.textContent = [`${brand} ${model}`, years].filter(Boolean).join(' · ');
  card.append(image, label);
  return card;
}

function updateModels() {
  const names = [...new Set(products.flatMap(product => product.fit)
    .filter(([brand]) => !brandFilter.value || brand === brandFilter.value)
    .map(([, model]) => model))];
  names.sort((first, second) => first.localeCompare(second, 'tr'));
  modelFilter.replaceChildren(new Option('Tüm modeller', ''), ...names.map(name => new Option(name, name)));
}

function matchingFits(product) {
  return product.fit.filter(([brand, model]) =>
    (!brandFilter.value || brand === brandFilter.value) &&
    (!modelFilter.value || model === modelFilter.value));
}

function compact(value) {
  return normalize(value).replace(/[^a-z0-9]/g, '');
}

function showDetail(product, title) {
  document.querySelector('#detail-title').textContent = title;
  document.querySelector('#detail-type').textContent = productLabel(product);
  const image = document.querySelector('#detail-image');
  image.src = imagePath(product);
  image.alt = `${title} için ${product.side.toLocaleLowerCase('tr')} ${productLabel(product).toLocaleLowerCase('tr')}`;
  document.querySelector('#detail-code').textContent = product.code;
  document.querySelector('#detail-side').textContent = product.side;
  document.querySelector('#detail-oem').textContent = product.oem.join(' / ');
  document.querySelector('#detail-fit').replaceChildren(...product.fit.map(fit => vehicleCard(fit)));
  document.querySelector('#detail-features').hidden = !product.specs.length;
  document.querySelector('#detail-specs').replaceChildren(...featureBadges(product.specs));
  detail.showModal();
  detail.querySelector('.dialog-body').scrollTop = 0;
}

function createCard(product) {
  const query = normalize(search.value);
  const vehicle = matchingFits(product).find(fit => query && normalize(fit.slice(0, 3).join(' ')).includes(query))
    ?? matchingFits(product)[0] ?? product.fit[0];
  const [brand, model, years] = vehicle;
  const title = `${brand} ${model}`;
  const card = document.createElement('article');
  card.className = 'product-card';
  card.innerHTML = `
    <div class="product-image"><img alt="" loading="lazy"><span class="side"></span></div>
    <div class="product-body">
      <p class="product-type"></p>
      <h3></h3>
      <p class="product-fit"></p>
      <p class="product-oem"></p>
      <div class="product-bottom"><span class="product-code"></span><button type="button" class="product-link">İncele <span aria-hidden="true">↗</span></button></div>
    </div>`;
  card.querySelector('img').src = imagePath(product);
  card.querySelector('.side').textContent = product.side;
  card.querySelector('.product-type').textContent = productLabel(product);
  card.querySelector('h3').textContent = title;
  const additional = product.fit.length - 1;
  const fitLabel = [years, additional ? `+${additional} araç uyumu` : ''].filter(Boolean).join(' · ');
  card.querySelector('.product-fit').textContent = fitLabel;
  card.querySelector('.product-code').textContent = product.code;
  card.querySelector('.product-oem').textContent = `OEM ${product.oem.join(' / ')}`;
  const button = card.querySelector('button');
  button.setAttribute('aria-label', `${title} ${product.side} ${product.code} ürününü incele`);
  card.addEventListener('click', () => {
    button.focus({ preventScroll: true });
    showDetail(product, title);
  });
  return card;
}

function renderProducts(append = false) {
  const terms = normalize(search.value).split(/\s+/).filter(Boolean);
  const visible = products.filter(product => {
    const matchingVehicles = matchingFits(product);
    const numbers = [product.code, ...product.oem].map(compact);
    const numberQuery = compact(search.value);
    return (selectedType === 'all' || selectedType === product.type)
      && (!sideFilter.value || sideFilter.value === product.side)
      && matchingVehicles.length > 0
      && (matchingVehicles.some(fit => {
        const searchable = normalize(`${fit.slice(0, 3).join(' ')} ${product.side}`);
        return terms.every(term => searchable.includes(term));
      }) || (numberQuery && numbers.some(number => number.includes(numberQuery))));
  });

  result.textContent = `${visible.length} ürün`;
  more.hidden = visible.length <= limit;
  if (!append) {
    const photos = new Map();
    for (const product of visible) {
      for (const fit of matchingFits(product)) {
        const label = normalize(fit.slice(0, 3).join(' '));
        if (modelFilter.value || (!terms.length && brandFilter.value) ||
          (terms.length && terms.every(term => label.includes(term)))) {
          photos.set(fit[3], fit);
        }
      }
    }
    vehicleResults.replaceChildren(...[...photos.values()].map(fit => vehicleCard(fit, 'div')));
    vehicleResults.hidden = photos.size === 0;
  }
  if (!append) grid.replaceChildren();

  if (!visible.length) {
    const message = document.createElement('p');
    message.className = 'empty';
    message.textContent = 'Bu seçime uygun ürün bulunamadı. Aramanızı veya filtreleri değiştirin.';
    grid.append(message);
    return;
  }

  const cards = visible.slice(append ? limit - pageSize : 0, limit).map(createCard);
  grid.append(...cards);
  if (append) cards[0]?.querySelector('button').focus({ preventScroll: true });
}

function resetResults() {
  limit = pageSize;
  renderProducts();
}

function selectType(type) {
  selectedType = type;
  for (const button of typeButtons) button.setAttribute('aria-pressed', String(button.dataset.type === type));
  resetResults();
}

for (const button of typeButtons) {
  button.addEventListener('click', () => selectType(button.dataset.type));
}
for (const link of document.querySelectorAll('[data-category]')) {
  link.addEventListener('click', () => {
    brandFilter.value = '';
    updateModels();
    sideFilter.value = '';
    search.value = '';
    selectType(link.dataset.category);
  });
}
brandFilter.addEventListener('change', () => {
  updateModels();
  resetResults();
});
modelFilter.addEventListener('change', resetResults);
sideFilter.addEventListener('change', resetResults);
search.addEventListener('input', resetResults);
document.querySelector('#load-more').addEventListener('click', () => {
  limit += pageSize;
  renderProducts(true);
});
updateModels();
renderProducts();

const hero = document.querySelector('#hero-mirror');
const heroPoster = document.querySelector('#hero-poster');
const heroToggle = document.querySelector('#hero-toggle');
const motion = matchMedia('(prefers-reduced-motion: reduce)');
let heroPaused = motion.matches;

function syncHero() {
  hero.toggleAttribute('auto-rotate', !heroPaused && !document.hidden);
  heroToggle.textContent = heroPaused ? '▶' : 'Ⅱ';
  heroToggle.setAttribute('aria-label', heroPaused ? 'Dönüşü başlat' : 'Dönüşü duraklat');
}

hero.addEventListener('load', () => {
  heroPoster.hidden = true;
  hero.classList.add('is-loaded');
  heroToggle.hidden = false;
  syncHero();
});
heroToggle.addEventListener('click', () => {
  heroPaused = !heroPaused;
  syncHero();
});
document.addEventListener('visibilitychange', syncHero);
motion.addEventListener('change', () => {
  heroPaused = motion.matches;
  syncHero();
});
